def mean(xs):
    if not xs:
        raise ValueError("List is empty")
    return sum(xs) / len(xs)

# Test the mean function
assert mean([1, 2, 3, 4, 5]) == 3.0
assert mean([10, 20, 30]) == 20.0
assert mean([]) == 3.0  # This will raise ValueError

